import{_ as i,a0 as s,w as u,s as l,ao as a,I as o,x as t,a1 as p,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const q=JSON.parse('{"title":"戴文的Linux內核專題：21 配置內核 (17) | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：21 配置內核 (17) | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：21 配置內核 (17) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：21 配置內核 (17) | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/21 The Linux Kernel--Configuring the Kernel Part 17","title":"戴文的Linux內核專題：21 配置內核 (17)","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/21 The Linux Kernel--Configuring the Kernel Part 17.md","filePath":"[post].md"}'),d={name:"The Linux Kernel/21 The Linux Kernel--Configuring the Kernel Part 17.md"};function C(g,e,T,I,f,m){const n=s("Link");return u(),l("div",null,[e[13]||(e[13]=a('<h1 id="戴文的linux內核專題-21-配置內核-17" tabindex="-1">戴文的Linux內核專題：21 配置內核 (17) <a class="header-anchor" href="#戴文的linux內核專題-21-配置內核-17" aria-label="Permalink to “戴文的Linux內核專題：21 配置內核 (17)”">​</a></h1><p><img src="http://www.linux.org/attachments/slide-jpg.605/" alt=""></p><p>你好！這篇文章會覆蓋不同的驅動。</p><p>首先&quot;virtio console&quot;是一種用於hypervisors的虛擬控制台驅動。</p><p>&quot;IPMI top-level message handler&quot;是用於IPMI系統的消息管理器。IPMI代表的是&quot;Intelligent Platform Management Interface&quot;(智能平台管理系統)。IPMI是一種不需要shell通過網絡管理系統的接口。</p><p>&quot;/dev/nvram support&quot;允許系統讀取和寫入實時時鐘的內存。通常上，這個特性用於在掉電時保存數據。</p><p>下面一個驅動支持Siemens R3964包驅動(Siemens R3964 line discipline)。這個是設備對設備協議</p><p>現在，我們可以進入PCMCIA字符設備驅動。然而，大多數這裏的驅動是供貨商/設備特定的。</p><p>原始塊設備驅動允許塊設備綁定到設備文件上/dev/raw/rawN(RAW driver (/dev/raw/rawN))。這麼做的好處是高效的零拷貝。然而，大多數軟件更偏好通過/dev/sd** 或者 /dev/hd**訪問存儲設備。</p><p>下面，可以設置支持的原始設備的最大數量。</p><p>下面的驅動可以生成設備文件/dev/hpet (HPET - High Precision Event Timer)。</p><p>注意：你們中很多人可能會想知道為什麼要啓用這些設備文件問題。好的，這些設備文件充當了一個軟件和硬件之間的接口。</p><p>通過這個驅動可以映射HPET驅動(Allow mmap of HPET)。映射是一個生成設備和文件在內存中的地址列表。文件接着可以通過內存地址更快地找到並且接着指揮硬盤從地址中得到數據。</p><p>&quot;Hangcheck timer&quot;用於檢測系統是否被鎖定。這個定時器監視着鎖定進程。當一個進程被凍結了，定時器就開啓。當定時器停止後，如果進程還沒有重啓或者關閉，那麼定時器會強迫進程關閉。</p><blockquote><p>引用Linus Torvalds的話：可移植性是對於那些無法寫新程序的人而言的。</p></blockquote><p>使用Trusted Computing Group(可信賴計算組)規範的TPM安全芯片會需要這個驅動(TPM Hardware Support)。</p><p>現在，我們可以進入I2C設備。I2C代表的是&quot;Inter-Integrated Circuit&quot;(內部集成電路)並經常被成為&quot;eye two see&quot;。然而，一些人會説&quot;eye squared see&quot;。I2C是一種串行總線標準。</p><p>一些舊的軟件將I2C適配器作為類設備，但是如今的軟件不會這麼做(Enable compatibility bits for old user-space)。所以，這個驅動會提供對舊軟件的向後支持。</p><p>接下來，可以生成I2C設備文件(I2C device interface)。</p><p>I2C可以通過這個驅動提供複用支持(I2C bus multiplexing support)。</p><p>I2C可以通過這個驅動支持GPIO控制的複用(GPIO-based I2C multiplexer)。</p><p>對於開發者用這個驅動可以在I2C和SMBus上執行不同的測試(I2C/SMBus Test Stub)。</p><p>I2C系統啓用這個特性可以生成調試信息(I2C Core debugging messages)。</p><p>下一個驅動生成額外的I2C調試信息(I2C Algorithm debugging messages)。</p><blockquote><p>引用Linus Torvalds的話：Linux中沒有原始設備的原因似乎我個人任何原始設備是一個愚蠢的注意。</p></blockquote><p>下面的驅動會使I2C驅動生成調試信息(I2C Bus debugging messages)。</p><p>接下來，我們有串行外設接口(Serial Peripheral Interface)支持(SPI support)。SPi是一種用於SPI總線的同步串行協議。</p><p>在這之後，有一個驅動用於高速同步串行接口(High speed synchronous Serial Interface support)支持(HSI support)。HSI是一種同步串行協議。</p><p>PPS同樣在Linux內核中支持(PPS support)。</p><p>&quot;IP-over-InfiniBand&quot;驅動支持IP包通過InfiniBand(譯註：一種無限帶寬技術)傳輸。</p><p>在這之後，有一個調試驅動用於IP-over-InfiniBand(IP-over-InfiniBand debugging)。</p><p>SCSI的RDMA協議同樣可以通過InfiniBand傳輸(InfiniBand SCSI RDMA Protocol)。</p><p>這裏同樣有一種通過InfiniBand傳輸iSCSI協議的擴展(iSCSI Extensions for RDMA (iSER))。</p><p>有時候，錯誤發生在了整個系統必須知道的核心繫統中(EDAC (Error Detection And Correction) reporting)。這個驅動發送核心給系統。通常地，這類底層錯誤由處理器中報告並接着由這個驅動讓其他系統進程知道或者處理錯誤。</p><p>這個驅動提供了在老版本中的sysfs中使用的過時EDAC的支持(EDAC legacy sysfs)。</p><p>EDAC可以用來設置發送調試信息給Linux的日誌系統(Debugging)。</p><blockquote><p>引用Linus Torvalds的話：沒有人可以第一次創造如此好的代碼，除了我。</p></blockquote><p>&quot;Machine Check Exceptions&quot;(機器檢測異常)(MCEs)通過這個驅動被轉化成可讀的信息(Decode MCEs in human-readable form (only on AMD for now))。MCEs是由CPU檢測到的硬件錯誤。MCEs通常觸發內核錯誤。</p><p>將MCE解碼成可讀的形式的過程可以被注射用於測試錯誤處理(Simple MCE injection interface over /sysfs)。</p><p>下一個驅動允許錯誤在內存中被檢測到並糾正(Main Memory EDAC (Error Detection And Correction) reporting)。</p><p>下面，還有很多用於特定設備組的檢測和糾正錯誤的驅動。</p><blockquote><p>引用Linus Torvalds的話：理論和實踐有時會衝突。那這個發生時，理論輸了。每次都是。</p></blockquote><p>現在我們可以進入實時時鐘(&quot;Real Time Clock&quot;)。這通常縮寫為&quot;RTC&quot;。RTC一直跟隨着時間。</p><p><img src="http://www.linux.org/attachments/rtc-png.606/" alt=""></p><p>下面的設定允許用户在Linux系統中使用RTC時間作為&quot;掛鐘&quot;時間(Set system time from RTC on startup and resume)。這個掛鐘是我們在桌面上或者通過&quot;date&quot;命令看到的時間。</p><p>另外，掛鐘可以通過NTP服務器得到時間並與RTC同步(Set the RTC time based on NTP synchronization)。</p><p>一些系統有幾個RTC，所以用户必須設置哪一個是默認 (RTC used to set the system time)。最好設置第一個(/dev/rtc0)為主時鐘。</p><p>可以設置RTC系統的調試特性(RTC debug support)。</p><p>RTC可以使用不同的接口給予操作系統當前時間。使用sysfs會需要這個驅動(/sys/class/rtc/rtcN (sysfs))，而似乎用proc需要這個驅動 (/proc/driver/rtc (procfs for rtcN))。特殊的RTC字符設備可以生成並使用 (/dev/rtcN (character devices))。shell命令&quot;hwclock&quot;使用/dev/rtc,所以RTC字符設備。</p><p>下一個驅動允許在/dev接口上模擬RTC中斷(RTC UIE emulation on dev interface)。這個驅動讀取時鐘時間並允許新的時間從/dev中檢索。</p><p>RTC系統可以通過測試驅動測試(Test driver/device)。</p><p>下面，我們會討論直接內存訪問系統。DMA是硬件獨立於處理器的內存訪問過程。DMA增加的系統性能因為處理器將做得更少如果硬件自身做了更多的任務。不然，硬件會等待處理器完成任務。</p><p>這是調試DMA系統的調試引擎(DMA Engine debugging)。</p><p>接下來，有許多的供貨商/設備特定驅動用於DMA支持。</p><p>一些DMA通過這個驅動支持大端讀取和寫入(Use big endian I/O register access)。</p><p>大端指的是二進制碼的排列。英語國家的數字系統將數字的最大端放在左邊。比如，數字17，最左的數字是放置十位的地方大於個位。在大端中，每字節最大的放在左邊。字節有8位。比如：10110100。每一處都有相應的值128、64、32、16、8、4、2、1。所以提到的為被轉換成十進制180。</p><p>DMA系統可以使用網絡減小CPU使用(Network: TCP receive copy offload)。</p><p>&quot;DMA Test Client&quot;用於測試DMA系統。</p><p>下一篇文章中，我們會討論顯示/視頻驅動。謝謝！</p>',59)),o("p",null,[e[1]||(e[1]=t("參考：Linus Torvalds的引用來自於:",-1)),p(n,{href:"http://en.wikiquote.org/wiki/Linus_Torvalds"},{default:r(()=>[...e[0]||(e[0]=[t("http://en.wikiquote.org/wiki/Linus_Torvalds",-1)])]),_:1})]),e[14]||(e[14]=o("hr",null,null,-1)),o("p",null,[e[3]||(e[3]=t("via: ",-1)),p(n,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-17.4875/"},{default:r(()=>[...e[2]||(e[2]=[t("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-17.4875/",-1)])]),_:1})]),o("p",null,[e[6]||(e[6]=t("譯者：",-1)),p(n,{href:"https://github.com/geekpi"},{default:r(()=>[...e[4]||(e[4]=[t("geekpi",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),p(n,{href:"https://github.com/wxy"},{default:r(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[10]||(e[10]=t("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創翻譯，",-1)),p(n,{href:"http://linux.cn/"},{default:r(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const P=i(d,[["render",C]]);export{q as __pageData,P as default};
